"""Shared checker wrapper. Original test bytes, pytest arguments and CTRF output are preserved."""
import argparse,base64,hashlib,importlib.metadata as metadata,json,os,sys,time
from pathlib import Path
from nodeid_phase_reporter import NodeidPhaseReporter,validate_ledger

def main():
 p=argparse.ArgumentParser();p.add_argument('--config',required=True);args=p.parse_args();c=json.loads(Path(args.config).read_bytes());source=hashlib.sha256(Path(__file__).read_bytes()).hexdigest();assert source==c['checkerSourceSha256'];test=Path(c['originalTestPath']);assert hashlib.sha256(test.read_bytes()).hexdigest()==c['originalTestSha256'];assert c['pytestArgs']==['-p','ctrf.main','--ctrf','/tmp/ctrf.json',c['originalTestPath'],'-rA','-o','cache_dir=/tmp/pipeline-pytest-cache'];sys.path.insert(0,'/opt/pipeline-checker/router');sys.path.insert(1,'/tests');os.environ['PYTEST_DISABLE_PLUGIN_AUTOLOAD']='1';import pytest
 Path('/tmp/pipeline-mailbox').mkdir(exist_ok=True);start=time.time();mono=time.monotonic();reporter=NodeidPhaseReporter();exit_code=int(pytest.main(c['pytestArgs'],plugins=[reporter]));raw=Path('/tmp/ctrf.json').read_bytes();assert len(raw)<=2*1024**2;ledger=reporter.ledger();validate_ledger(ledger,c['expectedTestNames'],exit_code);ledger_raw=json.dumps(ledger,separators=(',',':')).encode();assert len(ledger_raw)<=2*1024**2
 result={'protocol':'tb12-private-checker-result-v1','taskId':c['taskId'],'invocationId':c['invocationId'],'collectOnly':False,'exitCode':exit_code,'reward':int(exit_code==0),'ctrf':json.loads(raw),'ctrfRawSha256':hashlib.sha256(raw).hexdigest(),'ctrfRawBase64':base64.b64encode(raw).decode(),'nodeidLedger':ledger,'nodeidLedgerRawBase64':base64.b64encode(ledger_raw).decode(),'nodeidLedgerRawSha256':hashlib.sha256(ledger_raw).hexdigest(),'checkerSourceSha256':source,'numericGuestPid':os.getpid(),'numericParentPid':os.getppid(),'pythonVersion':sys.version,'pythonExecutable':sys.executable,'pythonExecutableSha256':hashlib.sha256(Path(sys.executable).read_bytes()).hexdigest(),'procStatus':Path('/proc/self/status').read_text(),'mountInfoSha256':hashlib.sha256(Path('/proc/self/mountinfo').read_bytes()).hexdigest(),'packages':{n:metadata.version(n) for n in c['packageNames']},'privateNamespaces':{n:os.readlink('/proc/self/ns/'+n) for n in ['pid','mnt','net']},'wallStart':start,'wallStop':time.time(),'monotonicSeconds':time.monotonic()-mono}
 Path('/tmp/checker-result.json').write_text(json.dumps(result));print('TB12_RESULT:'+json.dumps(result,separators=(',',':')),flush=True)
if __name__=='__main__':main()
